+import { MetricListResponse, InstagramMetric, LinkedInMetric, WebsiteMetric, Metric } from "@/types/marketing";
+
+export type { InstagramMetric, LinkedInMetric, WebsiteMetric, Metric };
+
+const API_BASE_URL = "/api";
+
+class MarketingApiError extends Error {
+  constructor(public status: number, public body: unknown) {
+    super(`Marketing API Error: ${status}`);
+    this.name = "MarketingApiError";
+  }
+}
+
+async function marketingRequest<T>(
+  path: string,
+  options: RequestInit = {}
+): Promise<T> {
+  const token = localStorage.getItem("access_token");
+  const headers: Record<string, string> = {
+    ...(options.headers as Record<string, string>),
+  };
+  if (token) {
+    headers["Authorization"] = `Bearer ${token}`;
+  }
+
+  if (!headers["Content-Type"] && !(options.body instanceof FormData)) {
+    headers["Content-Type"] = "application/json";
+  }
+
+  let response = await fetch(path, { ...options, headers });
+
+  if (response.status === 401) {
+    const refresh = localStorage.getItem("refresh_token");
+    if (refresh) {
+      try {
+        const refreshResponse = await fetch(`${API_BASE_URL}/auth/refresh`, {
+          method: "POST",
+          headers: { "Content-Type": "application/json" },
+          body: JSON.stringify({ refresh_token: refresh }),
+        });
+        if (refreshResponse.ok) {
+          const tokens = await refreshResponse.json();
+          localStorage.setItem("access_token", tokens.access_token);
+          headers["Authorization"] = `Bearer ${tokens.access_token}`;
+          response = await fetch(path, { ...options, headers });
+        } else {
+          localStorage.removeItem("access_token");
+          localStorage.removeItem("refresh_token");
+          window.location.href = "/login";
+          throw new MarketingApiError(401, null);
+        }
+      } catch {
+        localStorage.removeItem("access_token");
+        localStorage.removeItem("refresh_token");
+        window.location.href = "/login";
+        throw new MarketingApiError(401, null);
+      }
+    }
+  }
+
+  if (!response.ok) {
+    const body = await response.json().catch(() => null);
+    throw new MarketingApiError(response.status, body);
+  }
+
+  return response.json();
+}
+
+export const marketingApi = {
+  listMetrics: async (
+    metricType: "instagram" | "linkedin" | "website",
+    params?: { page?: number; page_size?: number; q?: string }
+  ): Promise<MetricListResponse> => {
+    const searchParams = new URLSearchParams();
+    if (params?.page) searchParams.set("page", String(params.page));
+    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
+    if (params?.q) searchParams.set("q", params.q);
+    const query = searchParams.toString();
+    const endpoint = `/api/${metricType}-metrics${query ? `?${query}` : ""}`;
+    const response = await marketingRequest<MetricListResponse>(endpoint, {
+      method: "GET",
+    });
+    return response;
+  },
+
+  createMetric: async (
+    metricType: "instagram" | "linkedin" | "website",
+    data: Record<string, unknown>
+  ): Promise<Metric> => {
+    const endpoint = `/api/${metricType}-metrics`;
+    const response = await marketingRequest<Metric>(endpoint, {
+      method: "POST",
+      body: JSON.stringify(data),
+    });
+    return response;
+  },
+
+  getMetric: async (metricType: "instagram" | "linkedin" | "website", id: string): Promise<Metric> => {
+    const endpoint = `/api/${metricType}-metrics/${id}`;
+    const response = await marketingRequest<Metric>(endpoint);
+    return response;
+  },
+
+  updateMetric: async (
+    metricType: "instagram" | "linkedin" | "website",
+    id: string,
+    data: Record<string, unknown>
+  ): Promise<Metric> => {
+    const endpoint = `/api/${metricType}-metrics/${id}`;
+    const response = await marketingRequest<Metric>(endpoint, {
+      method: "PATCH",
+      body: JSON.stringify(data),
+    });
+    return response;
+  },
+
+  deleteMetric: async (metricType: "instagram" | "linkedin" | "website", id: string): Promise<void> => {
+    const endpoint = `/api/${metricType}-metrics/${id}`;
+    await marketingRequest<void>(endpoint, {
+      method: "DELETE",
+    });
+  },
+};

