import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

const clientSchema = z.object({
  name: z.string().min(1, "Name is required"),
  code: z.string().min(1, "Code is required"),
  primary_email: z.string().email("Valid email required"),
  primary_phone: z.string().optional(),
  address: z.string().optional(),
  city: z.string().optional(),
  state: z.string().optional(),
  pincode: z.string().optional(),
  country: z.string().default("India"),
  gst_number: z.string().optional(),
  notes: z.string().optional(),
  contacts: z.array(z.object({
    name: z.string().min(1, "Contact name required"),
    email: z.string().email("Valid email required"),
    phone: z.string().optional(),
    designation: z.string().optional(),
    is_primary: z.boolean().default(false),
  })).optional(),
});

type ClientFormData = z.infer<typeof clientSchema>;

interface ClientFormProps {
  initialData?: Partial<ClientFormData>;
  onSubmit: (data: ClientFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function ClientForm({ initialData, onSubmit, onCancel, isLoading }: ClientFormProps) {
  const form = useForm<ClientFormData>({
    resolver: zodResolver(clientSchema),
    defaultValues: {
      country: "India",
      contacts: [],
      ...initialData,
    },
  });

  const handleSubmit = async (data: ClientFormData) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await onSubmit(data as any);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Client Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="name">Name *</Label>
              <Input id="name" {...form.register("name")} />
              {form.formState.errors.name && (
                <p className="text-sm text-red-500">{form.formState.errors.name.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="code">Code *</Label>
              <Input id="code" {...form.register("code")} />
              {form.formState.errors.code && (
                <p className="text-sm text-red-500">{form.formState.errors.code.message as string}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="primary_email">Primary Email *</Label>
              <Input id="primary_email" type="email" {...form.register("primary_email")} />
              {form.formState.errors.primary_email && (
                <p className="text-sm text-red-500">{form.formState.errors.primary_email.message as string}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="primary_phone">Primary Phone</Label>
              <Input id="primary_phone" {...form.register("primary_phone")} />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="address">Address</Label>
            <Textarea id="address" {...form.register("address")} />
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="city">City</Label>
              <Input id="city" {...form.register("city")} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="state">State</Label>
              <Input id="state" {...form.register("state")} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="pincode">Pincode</Label>
              <Input id="pincode" {...form.register("pincode")} />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="country">Country</Label>
              <Input id="country" {...form.register("country")} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="gst_number">GST Number</Label>
              <Input id="gst_number" {...form.register("gst_number")} />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user, require_role
from src.backend.core.roles import Role
from src.backend.db.session import get_db
from src.backend.models.user import User
from src.backend.schemas.training import (
    TrainingCreate,
    TrainingListResponse,
    TrainingRead,
    TrainingUpdate,
)
from src.backend.services.training_service import training_service

router = APIRouter(prefix="/api/training", tags=["training"])


@router.get("", response_model=TrainingListResponse)
def list_trainings(
    _: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
    q: str | None = None,
) -> TrainingListResponse:
    items, total, page, page_size = training_service.list_trainings_service(
        db, page=page, page_size=page_size, q=q
    )
    return TrainingListResponse(
        items=[TrainingRead.model_validate(t) for t in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post("", response_model=TrainingRead, status_code=status.HTTP_201_CREATED)
def create_training(
    body: TrainingCreate,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TrainingRead:
    from sqlalchemy.exc import IntegrityError

    try:
        training = training_service.create_training_service(db, body, current_user.id)
        return TrainingRead.model_validate(training)
    except IntegrityError as e:
        db.rollback()
        raise HTTPException(status_code=409, detail="Training ID already exists") from e


@router.get("/{training_id}", response_model=TrainingRead)
def get_training(
    training_id: uuid.UUID,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TrainingRead:
    training = training_service.get_training_service(db, training_id)
    if not training:
        raise HTTPException(status_code=404, detail="Training not found")
    return TrainingRead.model_validate(training)


@router.patch("/{training_id}", response_model=TrainingRead)
def update_training(
    training_id: uuid.UUID,
    body: TrainingUpdate,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> TrainingRead:
    training = training_service.update_training_service(db, training_id, body, current_user.id)
    if not training:
        raise HTTPException(status_code=404, detail="Training not found")
    return TrainingRead.model_validate(training)


@router.delete("/{training_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_training(
    training_id: uuid.UUID,
    current_user: User = Depends(require_role(Role.ADMIN)),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> None:
    success = training_service.soft_delete_training_service(db, training_id, current_user.id)
    if not success:
        raise HTTPException(status_code=404, detail="Training not found")

