import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const feedbackSchema = z.object({
  feedback_id: z.string().min(1, "Feedback ID is required"),
  date: z.string().min(1, "Date is required"),
  employee_id: z.string().min(1, "Employee ID is required"),
  survey_period: z.string().optional(),
  overall_satisfaction_score: z.number().min(1).max(5, "Score must be 1-5"),
  workload_score: z.number().min(1).max(5, "Score must be 1-5"),
  learning_score: z.number().min(1).max(5, "Score must be 1-5"),
  management_score: z.number().min(1).max(5, "Score must be 1-5"),
  culture_score: z.number().min(1).max(5, "Score must be 1-5"),
  comments: z.string().optional(),
});

type FeedbackFormData = z.infer<typeof feedbackSchema>;

interface EmployeeFeedbackFormProps {
  initialData?: Partial<FeedbackFormData>;
  onSubmit: (data: FeedbackFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function EmployeeFeedbackForm({ initialData, onSubmit, onCancel, isLoading }: EmployeeFeedbackFormProps) {
  const form = useForm<FeedbackFormData>({
    resolver: zodResolver(feedbackSchema),
    defaultValues: {
      survey_period: "Annual FY26",
      ...initialData,
    },
  });

  const handleSubmit = async (data: FeedbackFormData) => {
    await onSubmit(data);
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Employee Feedback Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="feedback_id">Feedback ID *</Label>
              <Input id="feedback_id" {...form.register("feedback_id")} />
              {form.formState.errors.feedback_id && (
                <p className="text-sm text-red-500">{form.formState.errors.feedback_id.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="date">Date *</Label>
              <Input id="date" type="date" {...form.register("date")} />
              {form.formState.errors.date && (
                <p className="text-sm text-red-500">{form.formState.errors.date.message}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="employee_id">Employee ID *</Label>
            <Input id="employee_id" placeholder="Enter employee UUID" {...form.register("employee_id")} />
            {form.formState.errors.employee_id && (
              <p className="text-sm text-red-500">{form.formState.errors.employee_id.message}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="survey_period">Survey Period</Label>
            <Select
              value={form.watch("survey_period")}
              onValueChange={(v) => form.setValue("survey_period", v)}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select period" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="Annual FY26">Annual FY26</SelectItem>
                <SelectItem value="Half-yearly FY26">Half-yearly FY26</SelectItem>
                <SelectItem value="Quarterly Q1 FY26">Quarterly Q1 FY26</SelectItem>
                <SelectItem value="Quarterly Q2 FY26">Quarterly Q2 FY26</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="overall_satisfaction_score">Overall Satisfaction (1-5) *</Label>
              <Input
                id="overall_satisfaction_score"
                type="number"
                min="1"
                max="5"
                {...form.register("overall_satisfaction_score", { valueAsNumber: true })}
              />
              {form.formState.errors.overall_satisfaction_score && (
                <p className="text-sm text-red-500">{form.formState.errors.overall_satisfaction_score.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="workload_score">Workload (1-5) *</Label>
              <Input
                id="workload_score"
                type="number"
                min="1"
                max="5"
                {...form.register("workload_score", { valueAsNumber: true })}
              />
              {form.formState.errors.workload_score && (
                <p className="text-sm text-red-500">{form.formState.errors.workload_score.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="learning_score">Learning (1-5) *</Label>
              <Input
                id="learning_score"
                type="number"
                min="1"
                max="5"
                {...form.register("learning_score", { valueAsNumber: true })}
              />
              {form.formState.errors.learning_score && (
                <p className="text-sm text-red-500">{form.formState.errors.learning_score.message}</p>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="management_score">Management (1-5) *</Label>
              <Input
                id="management_score"
                type="number"
                min="1"
                max="5"
                {...form.register("management_score", { valueAsNumber: true })}
              />
              {form.formState.errors.management_score && (
                <p className="text-sm text-red-500">{form.formState.errors.management_score.message}</p>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="culture_score">Culture (1-5) *</Label>
              <Input
                id="culture_score"
                type="number"
                min="1"
                max="5"
                {...form.register("culture_score", { valueAsNumber: true })}
              />
              {form.formState.errors.culture_score && (
                <p className="text-sm text-red-500">{form.formState.errors.culture_score.message}</p>
              )}
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="comments">Comments</Label>
            <Textarea id="comments" {...form.register("comments")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

import { useState } from "react";
import { TrainingList } from "@/components/hr/TrainingList";
import { HardwareIssueList } from "@/components/hr/HardwareIssueList";
import { AdminProcessList } from "@/components/hr/AdminProcessList";
import { EmployeeFeedbackList } from "@/components/hr/EmployeeFeedbackList";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

type HRTab = "trainings" | "hardware-issues" | "admin-processes" | "employee-feedback";

export function HRPage() {
  const [activeTab, setActiveTab] = useState<HRTab>("trainings");

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold">HR Management</h1>
        <p className="text-muted-foreground">Manage employees, training, hardware, admin processes, and satisfaction</p>
      </div>

      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as HRTab)}>
        <TabsList>
          <TabsTrigger value="trainings">Trainings</TabsTrigger>
          <TabsTrigger value="hardware-issues">Hardware Issues</TabsTrigger>
          <TabsTrigger value="admin-processes">Admin Processes</TabsTrigger>
          <TabsTrigger value="employee-feedback">Satisfaction</TabsTrigger>
        </TabsList>

        <TabsContent value="trainings">
          <TrainingList />
        </TabsContent>

        <TabsContent value="hardware-issues">
          <HardwareIssueList />
        </TabsContent>

        <TabsContent value="admin-processes">
          <AdminProcessList />
        </TabsContent>

        <TabsContent value="employee-feedback">
          <EmployeeFeedbackList />
        </TabsContent>
      </Tabs>
    </div>
  );
}

