import type {
  Training,
  TrainingListResponse,
  TrainingCreate,
  TrainingUpdate,
  HardwareIssue,
  HardwareIssueListResponse,
  HardwareIssueCreate,
  HardwareIssueUpdate,
  AdminProcess,
  AdminProcessListResponse,
  AdminProcessCreate,
  AdminProcessUpdate,
  EmployeeFeedback,
  EmployeeFeedbackListResponse,
  EmployeeFeedbackCreate,
  EmployeeFeedbackUpdate,
} from "@/types/hr";
import { request } from "./api";

export const hrApi = {
  listTrainings: (params?: { page?: number; page_size?: number; q?: string }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    return request<TrainingListResponse>(`/api/training${query ? `?${query}` : ""}`);
  },

  getTraining: (id: string) => request<Training>(`/api/training/${id}`),

  createTraining: (data: TrainingCreate) =>
    request<Training>("/api/training", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  updateTraining: (id: string, data: TrainingUpdate) =>
    request<Training>(`/api/training/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  deleteTraining: (id: string) =>
    request<void>(`/api/training/${id}`, { method: "DELETE" }),

  listHardwareIssues: (params?: { page?: number; page_size?: number; q?: string }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    return request<HardwareIssueListResponse>(`/api/hardware-issues${query ? `?${query}` : ""}`);
  },

  getHardwareIssue: (id: string) => request<HardwareIssue>(`/api/hardware-issues/${id}`),

  createHardwareIssue: (data: HardwareIssueCreate) =>
    request<HardwareIssue>("/api/hardware-issues", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  updateHardwareIssue: (id: string, data: HardwareIssueUpdate) =>
    request<HardwareIssue>(`/api/hardware-issues/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  deleteHardwareIssue: (id: string) =>
    request<void>(`/api/hardware-issues/${id}`, { method: "DELETE" }),

  listAdminProcesses: (params?: { page?: number; page_size?: number; q?: string }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    return request<AdminProcessListResponse>(`/api/admin-processes${query ? `?${query}` : ""}`);
  },

  getAdminProcess: (id: string) => request<AdminProcess>(`/api/admin-processes/${id}`),

  createAdminProcess: (data: AdminProcessCreate) =>
    request<AdminProcess>("/api/admin-processes", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  updateAdminProcess: (id: string, data: AdminProcessUpdate) =>
    request<AdminProcess>(`/api/admin-processes/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  deleteAdminProcess: (id: string) =>
    request<void>(`/api/admin-processes/${id}`, { method: "DELETE" }),

  listEmployeeFeedbacks: (params?: { page?: number; page_size?: number; q?: string }) => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    return request<EmployeeFeedbackListResponse>(`/api/employee-feedback${query ? `?${query}` : ""}`);
  },

  getEmployeeFeedback: (id: string) => request<EmployeeFeedback>(`/api/employee-feedback/${id}`),

  createEmployeeFeedback: (data: EmployeeFeedbackCreate) =>
    request<EmployeeFeedback>("/api/employee-feedback", {
      method: "POST",
      body: JSON.stringify(data),
    }),

  updateEmployeeFeedback: (id: string, data: EmployeeFeedbackUpdate) =>
    request<EmployeeFeedback>(`/api/employee-feedback/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),

  deleteEmployeeFeedback: (id: string) =>
    request<void>(`/api/employee-feedback/${id}`, { method: "DELETE" }),
};

